import re
from typing import List, Tuple

_TYPED_FIELD_NAME_RE = re.compile(r'^\*{0,2}[^\s,]+(\s*,\s*\*{0,2}[^\s,]+)*$')

def _split_typed_field_argument(fieldarg: str) -> Tuple[str, str]:
    fieldarg = fieldarg.strip()
    if not fieldarg:
        raise ValueError
    stack: List[str] = []
    candidates: List[int] = []
    in_ws = False
    for i, ch in enumerate(fieldarg):
        if ch in '([{<':
            stack.append(ch)
        elif ch in ')]}>':
            if stack:
                top = stack[-1]
                if (top, ch) in {('(', ')'), ('[', ']'), ('{', '}'), ('<', '>')}:
                    stack.pop()
        if ch.isspace() and not stack:
            if not in_ws:
                candidates.append(i)
                in_ws = True
        else:
            in_ws = False
    if not candidates:
        raise ValueError
    for pos in candidates:
        lhs = fieldarg[:pos].strip()
        rhs = fieldarg[pos:].strip()
        if lhs and rhs and _TYPED_FIELD_NAME_RE.match(rhs):
            return lhs, rhs
    return fieldarg.split(None, 1)

samples = [
    'SomeClass foo',
    'dict(str, str) opc_meta',
    'int a, b',
    'unsigned long value',
    'const char* ptr',
    'const char *ptr',
]
for s in samples:
    try:
        t,n = _split_typed_field_argument(s)
        print(f'{s!r} -> type={t!r}, name={n!r}')
    except Exception as e:
        print(f'{s!r} -> {e.__class__.__name__}: {e}')
